 ['compose','compose.onSend(fn)','Transform outgoing text. Receives text and {scope}.'],
 ['messages.read',"on('message', fn)",'Receive {id, scope, from, name, text} for incoming messages.'],
 ['messages.send','chats.send(scope, text)','Send a chat message.'],
 ['chats.read','chats.list()','List conversations with titles, peers, unread counts and last messages.'],
 ['contacts.read','contacts.name(id)','Read a contact’s display name.'],
 ['wallet.read','wallet.balance()','Read {minor, mentos}. This does not authorize spending.'],
 ['storage','storage.get / set / remove / keys','Per-plugin local storage: up to 500 keys, 64 KB each.'],
 ['notify','notify(text)','Show a short in-app notice.'],
 ['net','http.request(options, callback)','HTTPS requests; GET, POST, PUT, PATCH, DELETE, HEAD. Up to 2 MB and 6 concurrent requests.'],
 ['p2p','peers.list / send / on','Send up to 32 KB to the same plugin on a contact’s device.'],
 ['ui','ui.page / slot / tab / refresh','Build native pages, screen cards and a bottom-bar tab.'],
