 ['layout','layout.set / reset','Adjust tabs, screen elements, density, nav labels and feed image shape.'],
 ['none','log / me() / plugin','Log values, read the current identity, or inspect plugin metadata.'],
 ['none','timer.after / every / cancel','Seconds-based timers. Repeating timers have a 5-second minimum; 20 timers maximum.']
