 const nodes=[['text / title','text; text also accepts style: body, title, heading, strong, muted, mono, error'],['button','label, onTap, style: primary, outline, text'],['input','key, label, hint, value, multiline, onChange, onSubmit'],['switch / slider','label, value, onChange; switch: subtitle; slider: min, max'],['list','items: [{title, subtitle, trailing, onTap}]'],['stat / progress','stat: label, value; progress: value from 0 to 1, or omitted for a spinner'],['row / column / card','children: an array of nodes'],['divider / space','space accepts size']];
</script>
